import "./ItemMasVendido.css";
import { useState } from "react";

export default function ItemMasVendido({ 
  imagen, 
  nombre, 
  precio, 
  sucursal, 
  tipo = "Más vendido", // "Más vendido", "Top de la semana", etc
  esCombo = false,
  icono = "👑" // emoji por defecto
}) {

  const [isHovered, setIsHovered] = useState(false);

  return (
    <div 
      className="item-mas-vendido"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* FONDO CON EFECTO DE ORO Y DESTELLO */}
      <div className="item-mas-vendido__fondo-destello"></div>
      <div className="item-mas-vendido__sombra-dorada"></div>

      <div className="item-mas-vendido__contenedor">
        
        {/* SECCIÓN IZQUIERDA - IMAGEN */}
        <div className="item-mas-vendido__imagen-section">
          <div className="item-mas-vendido__imagen">
            <img src={imagen} alt={nombre} />
          </div>
        </div>

        {/* SECCIÓN DERECHA - CONTENIDO */}
        <div className="item-mas-vendido__contenido-section">
          
          {/* BADGE CON ICONO Y TIPO */}
          <div className="item-mas-vendido__badge">
            <span className="item-mas-vendido__icono">{icono}</span>
            <span className="item-mas-vendido__tipo">{tipo}</span>
          </div>

          {/* NOMBRE Y PRECIO */}
          <div className="item-mas-vendido__info">
            <h3 className="item-mas-vendido__nombre">{nombre}</h3>
            
            <p className="item-mas-vendido__precio">
              ${parseFloat(precio).toLocaleString("es-AR", {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2
              })}
            </p>

            {/* SUCURSAL (solo si es combo) */}
            {esCombo && sucursal && (
              <div className="item-mas-vendido__sucursal">
                📍 {sucursal}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* EFECTO DE DESTELLO AL HOVER */}
      <div className={`item-mas-vendido__destello ${isHovered ? 'active' : ''}`}></div>
    </div>
  );
}