import "./TarjetaProducto.css";

export default function TarjetaProducto({ imagen, nombre, cantidad, descuentoPorcentaje, vencimiento, precio, precioOriginal, sucursal, descripcion, esCombo = false }) {

  // Calcular precio con descuento si se pasa el porcentaje
  const precioConDescuento =
    descuentoPorcentaje > 0
      ? (precioOriginal - (precioOriginal * descuentoPorcentaje) / 100).toFixed(2)
      : precio;


  const fecha = new Date(vencimiento);

  const fechaFormateada = fecha.toLocaleDateString("es-AR", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric"
  });



  return (
    <div className={`tarjeta-producto ${esCombo ? "tarjeta-producto--combo" : ""}`}>
      <div className="tarjeta-producto__imagen">
        <img src={imagen} alt={nombre} />
        {!esCombo && descuentoPorcentaje > 0 && (
          <div className="tarjeta-producto__descuento">-{descuentoPorcentaje}% OFF</div>
        )}
        {vencimiento && <div className="tarjeta-producto__vencimiento">Vto: {fechaFormateada }</div>}
      </div>

      <div className="tarjeta-producto__contenido">
        <h3 className="tarjeta-producto__nombre">{nombre}</h3>

        {/* Mostrar descripción solo en combos */}
        {esCombo && (
          <p className="tarjeta-producto__descripcion" data-descripcion={descripcion}>{descripcion}</p>
        )}

        {/* Mostrar precios dependiendo del tipo */}
        {esCombo ? (
          <p className="tarjeta-producto__precio">
            ${parseFloat(precio).toLocaleString("es-AR")}
          </p>
        ) : (
          <>
            {descuentoPorcentaje > 0 && (
              <p className="tarjeta-producto__precio-original">
                ${precioOriginal.toLocaleString("es-AR")}
              </p>
            )}
            <p className="tarjeta-producto__precio">
              ${parseFloat(precioConDescuento).toLocaleString("es-AR")}
            </p>
          </>
        )}
        {sucursal &&
          <div className="tarjeta-producto__sucursal">
            {`Sucursal ${sucursal}`}
          </div>}
        {cantidad &&
          <div className="tarjeta-producto__sucursal" style={{ fontSize: '1.8rem' }}>
            {`Cantidad: ${cantidad}`}
          </div>}
      </div>
    </div>
  );
}
