import "./TarjetaSucursal.css";

export default function TarjetaSucursal({ nombre, direccion, imagen }) {
  // Generar enlace a Google Maps según la dirección
  const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(direccion)}`;

  return (
    <div className="tarjeta-sucursal">
      {/* Lado izquierdo - Información */}
      <div className="tarjeta-sucursal__info">
        <h2 className="tarjeta-sucursal__nombre">{nombre}</h2>
        <p className="tarjeta-sucursal__direccion">{direccion}</p>

        <a
          href={mapsUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="tarjeta-sucursal__boton"
        >
          📍 Ver ubicación
        </a>
      </div>

      {/* Lado derecho - Imagen */}
      <div className="tarjeta-sucursal__imagen">
        <img src={imagen} alt={`Sucursal ${nombre}`} />
      </div>
    </div>
  );
}
