import BotonPerfil from '../../Componentes/BotonPerfil/BotonPerfil'
import { useNavigate } from 'react-router-dom'
import EmblaCarousel from '../../Componentes/EmblaCarousel/EmblaCarousel'
import EmblaCarousel2 from '../../Componentes/EmblaCarousel/EmblaCarousel2'
import no_encontrado from '../../assets/no_encontrado.png'
import { useState, useEffect } from 'react'

import descuentos from '../../assets/descuento.png'
import leyseca from '../../assets/leysecalogo2.png'
import combo from '../../assets/combo.png'
import fondo_quienes from '../../assets/fondo_quienes_somos2.png'
import instragram from '../../assets/instagram.png'
import facebook from '../../assets/facebook.png'
import tiktok from '../../assets/tiktok.png'

import coca from '../../assets/marcas/coca.png'
import fernet from '../../assets/marcas/fernet.png'
import heineken from '../../assets/marcas/heineken.png'
import mirinda from '../../assets/marcas/mirinda.png'
import monster from '../../assets/marcas/monster.png'
import patagonia from '../../assets/marcas/patagonia.png'
import sevenup from '../../assets/marcas/sevenup.png'
import smirnoff from '../../assets/marcas/smirnoff.png'
import pepsi from '../../assets/marcas/pepsi.png'
import corona from '../../assets/corono_producto.png'



import '../../base.css'
import './Inicio.css'
import TarjetaProducto from '../../Componentes/TarjetaProducto/TarjetaProducto'
import ItemMasVendido from '../../Componentes/ItemMasVendido/ItemMasVendido'

// Constante del endpoint 
const API_ENDPOINT = import.meta.env.VITE_API_BASE_URL



export default function Inicio() {


  const navegarHacia = useNavigate()

  const clickIniciarSesion = () => {
    navegarHacia('/inicioSesion')
  }

  const marcasArray = [coca, fernet, heineken, mirinda, monster, patagonia, sevenup, smirnoff, pepsi]
  const marcasDuplicadas = [...marcasArray, ...marcasArray, ...marcasArray] // Triplicar para mejor loop



  //FUNCIONES PARA TRAER PRODUCTO Y COMBO MÁS VENDIDO
  // Estados para el producto y combo más vendido
  const [productoMasVendido, setProductoMasVendido] = useState(null)
  const [comboMasVendido, setComboMasVendido] = useState(null)
  const [cargando, setCargando] = useState(true)

  // Traer producto más vendido
  useEffect(() => {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/producto/masVendido`)
      .then(res => res.json())
      .then(data => {
        if (data.error) {
          console.error('Error al obtener producto más vendido:', data.error)
          return
        }
        setProductoMasVendido(data)
      })
      .catch(error => console.error('Error:', error))
  }, [])

  // Traer combo más vendido
  useEffect(() => {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/combo/masVendido`)
      .then(res => res.json())
      .then(data => {
        if (data.error) {
          console.error('Error al obtener combo más vendido:', data.error)
          return
        }
        setComboMasVendido(data)
        setCargando(false)
      })
      .catch(error => console.error('Error:', error))
  }, [])



  ////////////FUNCIONES AUXILIARES////////////////

  // Función para capitalizar cada palabra
  const capitalizarPalabras = (texto) => {
    return texto
      .split(' ')
      .map(palabra => palabra.charAt(0).toUpperCase() + palabra.slice(1).toLowerCase())
      .join(' ')
  }

  // Función para construir la URL completa de la imagen
  const construirUrlImagen = (rutaRelativa, esCombo, esSucursal) => {
    if (!rutaRelativa) return no_encontrado
    // Si ya contiene http, devuelve tal cual (por si acaso)
    if (rutaRelativa.startsWith('http')) return rutaRelativa
    // Si comienza con /, le agregamos el endpoint
    if (esCombo || esSucursal) {
      return `${API_ENDPOINT}${rutaRelativa}`
    }
    return `${API_ENDPOINT}/storage/${rutaRelativa}`
  }

  // Función para convertir array de productos en descripción
  const construirDescripcionProductos = (productosArray) => {
    if (!productosArray || productosArray.length === 0) return 'Sin productos'

    return productosArray
      .map(item => `${item.cantidad} ${capitalizarPalabras(item.producto)}`)
      .join(' + ')
  }


  // Función para transformar datos del backend al formato que necesita el carousel
  const transformarProductos = (productosBackend) => {
    return productosBackend.map(prod => ({
      nombre: capitalizarPalabras(prod.nombre),
      descuentoPorcentaje: prod.descuentoPorcentaje,
      precioOriginal: prod.precioOriginal,
      sucursal: prod.sucursal,
      imagen: construirUrlImagen(prod.imagen),
      vencimiento: prod.vencimiento
    }))
  }

  // Función para transformar combos del backend
  const transformarCombos = (combosBackend) => {
    let esCombo = true;
    return combosBackend.map(c => ({
      nombre: capitalizarPalabras(c.nombre),
      descripcion: construirDescripcionProductos(c.productos),
      precio: c.precio,
      sucursal: c.sucursal,
      imagen: construirUrlImagen(c.imagen, esCombo),
      vencimiento: c.vencimiento
    }))
  }

  /////////////TRAER PRODCUTOS
  const [productos, setProductos] = useState([]);

  useEffect(() => {
    fetch(`${API_ENDPOINT}/api/producto/descuentos`)
      .then(res => res.json())
      .then(data => {
        // Transformar los datos antes de guardarlos en el estado
        const productosTransformados = transformarProductos(data)
        setProductos(productosTransformados)
      })
      .catch(error => console.error('Error al obtener productos:', error))
  }, [])

  ///////////////TRAER COMBOS
  const [combos, setCombos] = useState([])

  useEffect(() => {
    fetch(`${API_ENDPOINT}/api/combo/mostrarActivados`)
      .then(res => res.json())
      .then(data => {
        const combosTransformados = transformarCombos(data)
        setCombos(combosTransformados)
      })
      .catch(error => console.error('Error al obtener combos:', error))
  }, [])


  //////////////////TRAER SUCURSALES
  const [sucursales, setSucursales] = useState([])

  useEffect(() => {
    fetch(`${API_ENDPOINT}/api/sucursal`)
      .then(res => res.json())
      .then(data => {
        // Transformar datos: capitalizar nombre y construir URL de imagen
        let esSucursal = true;
        const sucursalesTransformadas = data.map(suc => ({
          nombre: capitalizarPalabras(suc.nombre),
          direccion: `${suc.direccion}, ${suc.ciudad}, ${suc.provincia}`,
          imagen: construirUrlImagen(suc.imagen, esSucursal)
        }))
        setSucursales(sucursalesTransformadas)
      })
      .catch(error => console.error('Error al obtener sucursales:', error))
  }, [])


  const OPTIONS = { loop: true }




  //LAYOUT
  return (

    <>
      <div className="__topbar">
        <div className="__topbar_logo_seccion">
          <img src={leyseca} alt="Ley Seca" className="__topbar_logo" />
          <span className="__topbar_nombre_empresa">LEY SECA</span>
        </div>

        <div className='__boton_perfil __boton_perfil_imagen'>
          <BotonPerfil onClick={clickIniciarSesion} />
        </div>
      </div>

      <main className="__scroll_container">
        <section className="__seccion_descuentos">
          <div className="__franja_superior">
            <div className="__logo_leyseca __logo_leyseca--floating">
              <img src={leyseca} alt="Ley Seca Logo" />
            </div>
            <div className="__franja_redes">
              <a href="https://facebook.com" target="_blank"><img src={facebook} alt="Facebook" /></a>
              <a href="https://instagram.com" target="_blank"><img src={instragram} alt="Instagram" /></a>
              <a href="https://tiktok.com" target="_blank"><img src={tiktok} alt="TikTok" /></a>
            </div>

          </div>

          <div className="__contenedor_descuentos">
            <div className="__columna_izquierda">
              <h2 className='__titulo_sucursales'>Descuentos del día</h2>
              <img src={descuentos} alt="Descuento del día" className="__img_descuento" />
            </div>

            <div className="__columna_derecha">
              <EmblaCarousel slides={productos} options={OPTIONS} tiempo={3000} descuentos />
            </div>
          </div>
        </section>

        <section className='__seccion_combos'>
          <div className="__tarjeta_superior_combo">
            {productoMasVendido && <ItemMasVendido
              imagen={construirUrlImagen(productoMasVendido.imagen, true)}
              nombre={capitalizarPalabras(productoMasVendido.nombre)}
              precio={productoMasVendido.precio}
              tipo="Más vendido de la semana"
              esCombo={false}
              icono="👑"
            />}
            {comboMasVendido &&
              <ItemMasVendido
                imagen={construirUrlImagen(comboMasVendido.imagen, true)}
                nombre={capitalizarPalabras(comboMasVendido.nombre)}
                precio={comboMasVendido.precio}
                sucursal={comboMasVendido.sucursal}
                tipo="Combo Destacado"
                esCombo={true}
                icono="🎁"
              />}
          </div>
          <div className="__contenedor_combos" >
            <div className="__columna_izquierda">
              <EmblaCarousel slides={combos} options={OPTIONS} tiempo={3000} combos />
            </div>
            <div className="__columna_derecha">
              <h2 className='__titulo_sucursales'>Combos del día</h2>
              <img src={combo} alt="Combos del día" className="__img_combo" />
            </div>
          </div>
        </section>

        <section className='__seccion_quienes'>
          <div style={{ margin: "6rem 0 2rem 2rem" }}>
            <h2 className='__titulo_ofertas'>Quiénes somos</h2>
            <p>Somos Ley Seca, tu licorería de confianza en Salta, con sucursales en toda la provincia.</p>
          </div>
          <div className="__contenedor_acordeon">
            <div className="__acordeon">
              <details>
                <summary>Información general</summary>
                <p>Somos una cadena salteña con años de experiencia ofreciendo los mejores licores, vinos y cervezas artesanales del país.</p>
              </details>

              <details>
                <summary>Productos que manejamos</summary>
                <p>Contamos con una amplia variedad de bebidas: vinos, cervezas nacionales e importadas, whiskies, aperitivos y más.</p>
              </details>

              <details>
                <summary>Nuestras sucursales</summary>
                <p>Tenemos presencia en Salta Capital, Orán, San Lorenzo y Vaqueros. Cada local mantiene la misma calidad y atención personalizada.</p>
              </details>

              <details>
                <summary>Compromiso con el cliente</summary>
                <p>Ofrecemos precios competitivos, promociones constantes y asesoramiento para garantizar la mejor elección para cada ocasión.</p>
              </details>
            </div>
          </div>
          <img src={fondo_quienes} alt="Decoración Quiénes somos" className='__img_quienes' />

        </section>

        <section className='__seccion_sucursales'>
          <div className="__sucursales_wrapper">
            <h2 className='__titulo_sucursales'>Sucursales</h2>
            <div className="__carousel_sucursales">
              <EmblaCarousel2 slides={sucursales} options={{ axis: 'y', loop: true }} />
            </div>
          </div>


          <div className="__marcas_section">
            <h3 className='__titulo_marcas'>Nuestras Marcas</h3>
            <div className="__marcas_carousel_container">
              <div className="__marcas_carousel">
                {marcasDuplicadas.map((marca, index) => (
                  <div key={index} className="__marca_item_inicio">
                    <img src={marca} alt={`Marca ${index}`} />
                  </div>
                ))}
              </div>
            </div>
          </div>
        </section>

      </main>
    </>
  )
}
