import React from 'react'
import { DotButton, useDotButton } from './EmblaCarouselDotButton'
import { PrevButton, NextButton, usePrevNextButtons } from './EmblaCarouselArrowButtons2'
import useEmblaCarousel from 'embla-carousel-react'
import TarjetaSucursal from '../TarjetaSucursal/TarjetaSucursal'
import '../../embla2.css'

const EmblaCarousel2 = ({ slides, options }) => {
  const [emblaRef, emblaApi] = useEmblaCarousel(options)

  const { selectedIndex, scrollSnaps, onDotButtonClick } = useDotButton(emblaApi)
  const {
    prevBtnDisabled,
    nextBtnDisabled,
    onPrevButtonClick,
    onNextButtonClick
  } = usePrevNextButtons(emblaApi)

  return (
    <section className="embla2">
      <div className="embla2__viewport" ref={emblaRef}>
        <div className="embla2__container">
          {slides.map((sucursal, index) => (
            <div className="embla2__slide" key={index}>
              <TarjetaSucursal
                nombre={sucursal.nombre}
                direccion={sucursal.direccion}
                imagen={sucursal.imagen}
              />
            </div>
          ))}
        </div>
      </div>

      <div className="embla2__controls">
        <div className="embla2__buttons">
          <PrevButton onClick={onPrevButtonClick} disabled={prevBtnDisabled} />
          <NextButton onClick={onNextButtonClick} disabled={nextBtnDisabled} />
        </div>

      
      </div>
    </section>
  )
}

export default EmblaCarousel2
