import { useNavigate } from 'react-router-dom';
import { useUsuarioStore } from '../store/Usuario';

export const useFuncionesPerfil = () => {
    const { cierraSesion, token } = useUsuarioStore(); //funcion de cierre sesion de la store

    const navegarHacia = useNavigate();

    const cerrarSesion = async () => {

        try {
            if (!token) {
                console.warn("Intentando cerrar sesión sin token");
                cierraSesion();
                navegarHacia('/inicioSesion');
                return;
            }
            console.log("Cerrando sesión con token:", token);
            const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/usuario/cerrarSesion`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
            });

            cierraSesion();
            navegarHacia('/inicioSesion');
        } catch (error) {
            console.error("Error al cerrar sesión:", error);
            cierraSesion();
            navegarHacia('/inicioSesion');
        }
    };

    const acciones = {
        irAPerfil: () => navegarHacia('/perfil'),
        irAConfiguraciones: () => navegarHacia('/perfil/configuraciones'),
        cerrarSesion
    };

    return acciones;
};